import os
import google.generativeai as genai

def check_safety(text: str):
    """
    Checks the given text for unsafe content using Google's Generative AI.

    Args:
        text: The text content to check for safety.

    Returns:
        A dictionary indicating if the content is safe and any safety ratings.
    """
    # Configure the API key
    genai.configure(api_key=os.getenv("GOOGLE_API_KEY"))

    model = genai.GenerativeModel('gemini-pro')

    safety_settings = [
        {
            "category": "HARM_CATEGORY_HARASSMENT",
            "threshold": "BLOCK_MEDIUM_AND_ABOVE"
        },
        {
            "category": "HARM_CATEGORY_HATE_SPEECH",
            "threshold": "BLOCK_MEDIUM_AND_ABOVE"
        },
        {
            "category": "HARM_CATEGORY_SEXUALLY_EXPLICIT",
            "threshold": "BLOCK_MEDIUM_AND_ABOVE"
        },
        {
            "category": "HARM_CATEGORY_DANGEROUS_CONTENT",
            "threshold": "BLOCK_MEDIUM_AND_ABOVE"
        },
    ]

    try:
        response = model.generate_content(
            text,
            safety_settings=safety_settings
        )

        if response._chunks:
            # If there are chunks, it means the content was blocked.
            # The actual safety feedback is in the prompt_feedback.
            return {
                "is_safe": False,
                "safety_ratings": [
                    {"category": rating.category.name, "probability": rating.probability.name, "blocked": rating.blocked}
                    for rating in response.prompt_feedback.safety_ratings
                ]
            }
        else:
            return {
                "is_safe": True,
                "safety_ratings": [
                    {"category": rating.category.name, "probability": rating.probability.name, "blocked": rating.blocked}
                    for rating in response.prompt_feedback.safety_ratings
                ]
            }

    except Exception as e:
        # Handle cases where the content is blocked before full generation
        # or other API errors.
        return {
            "is_safe": False,
            "error": str(e)
        }

class ModelRequest:
    def __init__(self, prompt: str, max_tokens: int = 100, temperature: float = 0.7):
        self.prompt = prompt
        self.max_tokens = max_tokens
        self.temperature = temperature

    def to_dict(self):
        return {
            "prompt": self.prompt,
            "max_tokens": self.max_tokens,
            "temperature": self.temperature,
        }

class ModelResponse:
    def __init__(self, generated_text: str, model_id: str = "unknown"):
        self.generated_text = generated_text
        self.model_id = model_id

    def to_dict(self):
        return {
            "generated_text": self.generated_text,
            "model_id": self.model_id,
        }

def normalize_text(text: str) -> str:
    """
    Normalizes text by stripping whitespace and converting to lowercase.
    """
    return text.strip().lower()
